/* Device-local adapter for the prototype. Replace behind this boundary after IT approval. */
(function(root,factory){if(typeof module==='object'&&module.exports)module.exports=factory();else root.QuestStorage=factory();})(typeof globalThis!=='undefined'?globalThis:this,function(){
'use strict';
function createAdapter(storage,key){return {load(){try{const data=storage.getItem(key);return data?JSON.parse(data):null;}catch{return null;}},save(data){try{storage.setItem(key,JSON.stringify(data));return {saved:true};}catch{return {saved:false};}}};}
function historySnapshot(job,previous,kind,at,id,detail={}){return {id,at,unitId:job.unitId,shiftCapacityMinutes:job.shiftCapacityMinutes,allocationExplicit:!!job.allocationExplicit,actualMinutes:job.actualMinutes??null,delayMinutes:job.delayMinutes??null,delayReason:job.delayReason||'',assignmentId:job.id,previousAssignmentId:job.previousAssignmentId||null,hand:job.hand||'',date:job.date,shift:job.shift,cell:job.cell,operators:job.operators,job:job.job,part:job.part,processId:job.processId,from:previous?.end??job.start,start:job.start,to:job.end,goal:job.goal,total:job.total,gap:job.end-job.goal,status:job.status,closed:job.closed,training:!!job.training,productiveMinutes:job.productiveMinutes,overtimeMinutes:job.overtimeMinutes,configRevision:job.configRevision,goalRule:job.goalRule||'whole',stepMinutes:[...job.stepMinutes],rateMultiplier:job.rateMultiplier,comment:job.comment,kind,...detail};}
// Numbers stay numeric; text that a spreadsheet would run as a formula is prefixed with an apostrophe.
function csvCell(value){if(typeof value==='number')return Number.isFinite(value)?String(value):'';let s=String(value??'');if(/^\s*[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
return {createAdapter,historySnapshot,csvCell};
});
